<?php $categories=$categories??[]; ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Fee Structure | EduSasa</title><style>body{font-family:system-ui,sans-serif;background:#f6f7fb;color:#172033}.wrap{max-width:900px;margin:30px auto;padding:18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:20px}input,select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #ccd1db;border-radius:8px;margin:6px 0 12px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.item{display:grid;grid-template-columns:1fr 160px 180px 90px;gap:8px;align-items:end;margin-bottom:8px}button,a{padding:9px 13px;border:0;border-radius:8px;background:#172033;color:#fff;text-decoration:none}.muted{color:#667085}@media(max-width:700px){.grid,.item{grid-template-columns:1fr}}</style></head><body><main class="wrap"><p><a href="/finance/fee-structures">← Fee Structures</a></p><h1>Create Fee Structure</h1><section class="card"><form method="post" action="/finance/fee-structures"><input type="hidden" name="_token" value="<?= htmlspecialchars((string)($_SESSION['_csrf']??''),ENT_QUOTES) ?>"><label>Structure name</label><input name="name" required placeholder="Term 1 2027 — Grade 4"><div class="grid"><div><label>Target class ID <span class="muted">(optional)</span></label><input type="number" name="target_class_id" min="1" placeholder="All classes"></div><div><label>Target stream ID <span class="muted">(optional)</span></label><input type="number" name="target_stream_id" min="1" placeholder="All streams"></div><div><label>Academic year ID <span class="muted">(optional)</span></label><input type="number" name="academic_year_id" min="1"></div><div><label>Term ID <span class="muted">(optional)</span></label><input type="number" name="term_id" min="1"></div></div><h2>Fee items</h2><p class="muted">Each amount is charged once per student when the batch is generated.</p><div id="items"><div class="item"><input name="item_name[]" placeholder="Tuition" required><input name="item_amount[]" type="number" min="0.01" step="0.01" placeholder="Amount" required><select name="category_id[]" required><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>"><?= htmlspecialchars($c['name']) ?></option><?php endforeach; ?></select><label><input type="checkbox" name="mandatory[0]" value="1" checked> Required</label></div></div><button type="button" onclick="addItem()">+ Add item</button> <button type="submit">Save draft</button></form></section></main><script>let n=1;function addItem(){const root=document.getElementById('items');const el=document.createElement('div');el.className='item';el.innerHTML='<input name="item_name[]" placeholder="Fee item" required><input name="item_amount[]" type="number" min="0.01" step="0.01" placeholder="Amount" required><select name="category_id[]"><?= implode('',array_map(fn($c)=>'<option value="'.(int)$c['id'].'">'.htmlspecialchars($c['name'],ENT_QUOTES).'</option>',$categories)) ?></select><label><input type="checkbox" name="mandatory['+n+']" value="1" checked> Required</label>';root.appendChild(el);n++;}</script></body></html>
